INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(3351, '초간단 카레라이스', '양배추 200g, 버섯 100g, 배즙 3큰술, 두부 1모', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 29, 25, 3.4, 'RCP_3351', 0),
(3352, '부산식 설렁탕', '새송이버섯 2개, 식용유 2큰술, 다진마늘 1큰술, 파프리카 1개', '1. 양념장을 넣고 골고루 섞는다\n2. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n3. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 24, 13, 4.2, 'RCP_3352', 0),
(3353, '가을 가지볶음', '삼겹살 300g, 양파 1개, 참기름 1큰술, 생강 1쪽, 계란 2개, 된장 2큰술, 두부 1모', '1. 뚜껑을 덮고 15분간 끓인다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 41, 1, 4.0, 'RCP_3353', 0),
(3354, '간단 치킨스테이크', '맛술 1큰술, 고춧가루 1큰술, 떡 300g, 시금치 100g, 무 200g', '1. 재료를 깨끗이 씻어 준비한다\n2. 소금으로 간을 맞춘다\n3. 냄비에 육수를 넣고 끓인다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 25, 19, 4.0, 'RCP_3354', 0),
(3355, '도시락용 떡볶이분식', '배즙 3큰술, 돼지고기 200g, 깨소금 1작은술, 고추 2개, 참기름 1큰술', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 재료를 깨끗이 씻어 준비한다\n5. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 17, 16, 4.2, 'RCP_3355', 0),
(3356, '겨울 피망볶음', '소고기 300g, 깨소금 1작은술, 김치 300g, 된장 2큰술, 부추 100g, 가지 2개', '1. 재료를 깨끗이 씻어 준비한다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 그릇에 담아 깨소금을 뿌린다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 29, 9, 1.0, 'RCP_3356', 0),
(3357, '제주식 곰탕', '새우 200g, 다진마늘 1큰술, 양파 1개, 브로콜리 1개, 소고기 300g, 두부 1모, 맛술 1큰술, 당근 1/2개', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 소금으로 간을 맞춘다\n3. 두부를 넣고 5분 더 끓인다\n4. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 32, 21, 2.0, 'RCP_3357', 0),
(3358, '도시락용 된장볶음', '생강 1쪽, 멸치 육수 500ml, 맛술 1큰술, 새우 200g, 무 200g', '1. 대파를 넣고 한소끔 끓인다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 밥과 함께 담아낸다', 'EXTERNAL_API', 48, 27, 2.3, 'RCP_3358', 0),
(3359, '여름 핫도그', '새우 200g, 두부 1모, 느타리버섯 100g, 멸치 육수 500ml, 파프리카 1개, 간장 3큰술, 돼지고기 200g, 배추 300g', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 참기름을 두르고 불을 끈다\n3. 접시에 보기 좋게 담아낸다\n4. 뚜껑을 덮고 15분간 끓인다', 'EXTERNAL_API', 44, 9, 4.0, 'RCP_3359', 0),
(3360, '인천식 콩비지찌개', '시금치 100g, 다진마늘 1큰술, 돼지고기 200g, 새송이버섯 2개, 간장 3큰술, 호박 1/2개', '1. 냄비에 육수를 넣고 끓인다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 약불에서 30분간 푹 끓인다\n5. 소금으로 간을 맞춘다', 'EXTERNAL_API', 29, 23, 4.9, 'RCP_3360', 0),
(3361, '도시락용 전복죽', '표고버섯 4개, 호박 1/2개, 미역 20g, 계란 2개, 소고기 300g, 당근 1/2개, 고춧가루 1큰술', '1. 양념을 만들어 재료에 버무린다\n2. 참기름을 두르고 불을 끈다\n3. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 41, 7, 3.2, 'RCP_3361', 0),
(3362, '무밥(프리미엄)', '소고기 300g, 된장 2큰술, 새송이버섯 2개, 계란 2개', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 대파를 넣고 한소끔 끓인다\n3. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 2, 10, 4.3, 'RCP_3362', 0),
(3363, '소갈비구이(다이어트)', '돼지고기 200g, 가지 2개, 콩나물 200g, 감자 2개, 된장 2큰술, 고추장 2큰술, 두부 1모', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 양념장을 넣고 골고루 섞는다\n3. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 16, 26, 3.3, 'RCP_3363', 0),
(3364, '여름 양념돼지갈비', '오징어 1마리, 새우 200g, 피망 1개, 쌀 2컵, 대파 1대, 미역 20g, 맛술 1큰술, 새송이버섯 2개', '1. 양념장을 넣고 골고루 섞는다\n2. 참기름을 두르고 불을 끈다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 36, 24, 1.9, 'RCP_3364', 0),
