INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(4851, '부산식 매운오징어볶음', '오징어 1마리, 소금 약간, 고춧가루 1큰술, 당근 1/2개', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 야채를 적당한 크기로 썰어 준비한다\n4. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 47, 6, 1.8, 'RCP_4851', 0),
(4852, '치즈닭갈비(특제)', '새송이버섯 2개, 시금치 100g, 마늘 5쪽, 두부 1모, 간장 3큰술, 양배추 200g, 돼지고기 200g, 당근 1/2개', '1. 접시에 보기 좋게 담아낸다\n2. 재료를 깨끗이 씻어 준비한다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 42, 19, 2.8, 'RCP_4852', 0),
(4853, '여름 해물볶음밥', '무 200g, 대파 1대, 부추 100g, 새송이버섯 2개, 마늘 5쪽', '1. 대파를 넣고 한소끔 끓인다\n2. 재료를 깨끗이 씻어 준비한다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 참기름을 두르고 불을 끈다\n5. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 47, 15, 2.2, 'RCP_4853', 0),
(4854, '가을 갈치구이', '설탕 1큰술, 피망 1개, 시금치 100g, 마늘 5쪽, 삼겹살 300g, 다진마늘 1큰술, 생강 1쪽, 밀가루 1컵', '1. 냄비에 육수를 넣고 끓인다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 야채를 적당한 크기로 썰어 준비한다\n4. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 9, 10, 4.7, 'RCP_4854', 0),
(4855, '봄 연근조림', '오징어 1마리, 소고기 300g, 쌈장 2큰술, 버섯 100g, 식용유 2큰술, 계란 2개, 감자 2개, 무 200g', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 밥과 함께 담아낸다', 'EXTERNAL_API', 47, 6, 3.1, 'RCP_4855', 0),
(4856, '다이어트용 LA갈비구이', '멸치 육수 500ml, 버섯 100g, 계란 2개, 대파 1대, 다진마늘 1큰술', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 뚜껑을 덮고 15분간 끓인다\n3. 냄비에 육수를 넣고 끓인다\n4. 양념장을 넣고 골고루 섞는다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 15, 18, 1.3, 'RCP_4856', 0),
(4857, '여름 매운갈비찜', '쌈장 2큰술, 다진마늘 1큰술, 깨소금 1작은술, 떡 300g, 간장 3큰술, 대파 1대', '1. 양념을 만들어 재료에 버무린다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 29, 16, 4.4, 'RCP_4857', 0),
(4858, '인천식 날치알김밥', '김치 300g, 떡 300g, 당면 200g, 연근 200g, 깨소금 1작은술, 브로콜리 1개, 마늘 5쪽, 돼지고기 200g', '1. 재료를 깨끗이 씻어 준비한다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 접시에 보기 좋게 담아낸다\n4. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 13, 7, 4.6, 'RCP_4858', 0),
(4859, '만두찌개(간편)', '김치 300g, 고춧가루 1큰술, 새우 200g, 물 500ml, 부추 100g, 느타리버섯 100g', '1. 고기를 먹기 좋은 크기로 썬다\n2. 재료를 깨끗이 씻어 준비한다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 15, 3, 1.9, 'RCP_4859', 0),
(4860, '시래기된장찌개(프리미엄)', '김치 300g, 깨소금 1작은술, 식용유 2큰술, 버섯 100g', '1. 야채를 데쳐서 찬물에 헹군다\n2. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다\n4. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 37, 28, 4.7, 'RCP_4860', 0),
(4861, '족발(순한맛)', '닭고기 400g, 파프리카 1개, 대파 1대, 고춧가루 1큰술, 부추 100g, 떡 300g', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 9, 3, 4.8, 'RCP_4861', 0),
(4862, '여름 파전', '참기름 1큰술, 깻잎 10장, 간장 3큰술, 새송이버섯 2개', '1. 두부를 넣고 5분 더 끓인다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 17, 16, 4.0, 'RCP_4862', 0),
(4863, '찹쌀밥(고단백)', '간장 3큰술, 마늘 5쪽, 호박 1/2개, 깨소금 1작은술, 닭고기 400g, 설탕 1큰술, 감자 2개, 새송이버섯 2개', '1. 고기를 먹기 좋은 크기로 썬다\n2. 재료를 깨끗이 씻어 준비한다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다\n4. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 33, 18, 3.5, 'RCP_4863', 0),
(4864, '짬뽕(순한맛)', '김치 300g, 양파 1개, 감자 2개, 고추 2개', '1. 냄비에 육수를 넣고 끓인다\n2. 소금으로 간을 맞춘다\n3. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n4. 두부를 넣고 5분 더 끓인다\n5. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 43, 29, 1.6, 'RCP_4864', 0),
(4865, '서울식 미역국', '배즙 3큰술, 버섯 100g, 양배추 200g, 양파 1개', '1. 참기름을 두르고 불을 끈다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 소금으로 간을 맞춘다', 'EXTERNAL_API', 20, 25, 3.5, 'RCP_4865', 0),
(4866, '대구식 김치라면', '미역 20g, 쌀 2컵, 대파 1대, 김치 300g', '1. 그릇에 담아 깨소금을 뿌린다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 약불에서 30분간 푹 끓인다\n4. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 14, 3, 2.4, 'RCP_4866', 0),
(4867, '참치김밥(특제)', '파프리카 1개, 간장 3큰술, 대파 1대, 부추 100g, 소금 약간, 떡 300g', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 소금으로 간을 맞춘다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n5. 야채를 데쳐서 찬물에 헹군다', 'EXTERNAL_API', 41, 1, 1.1, 'RCP_4867', 0),
(4868, '다이어트용 흑미밥', '새우 200g, 배즙 3큰술, 느타리버섯 100g, 고추장 2큰술, 부추 100g', '1. 밥과 함께 담아낸다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 42, 18, 3.8, 'RCP_4868', 0),
(4869, '버섯된장찌개(저칼로리)', '파프리카 1개, 김치 300g, 참기름 1큰술, 삼겹살 300g, 생강 1쪽, 멸치 육수 500ml, 배즙 3큰술, 쌀 2컵', '1. 밥과 함께 담아낸다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 재료를 깨끗이 씻어 준비한다\n5. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 50, 13, 4.9, 'RCP_4869', 0),
(4870, '부대찌개(간편)', '콩나물 200g, 오징어 1마리, 느타리버섯 100g, 밀가루 1컵, 새우 200g, 삼겹살 300g', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 19, 29, 3.9, 'RCP_4870', 0),
(4871, '다이어트용 채소잡채', '쌈장 2큰술, 당근 1/2개, 쌀 2컵, 당면 200g, 가지 2개', '1. 재료를 깨끗이 씻어 준비한다\n2. 대파를 넣고 한소끔 끓인다\n3. 약불에서 30분간 푹 끓인다\n4. 양념을 만들어 재료에 버무린다\n5. 야채를 데쳐서 찬물에 헹군다', 'EXTERNAL_API', 31, 11, 2.7, 'RCP_4871', 0),
(4872, '간단 샐러드', '김치 300g, 콩나물 200g, 당면 200g, 소고기 300g, 멸치 육수 500ml, 계란 2개', '1. 그릇에 담아 깨소금을 뿌린다\n2. 대파를 넣고 한소끔 끓인다\n3. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n4. 밥과 함께 담아낸다\n5. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 35, 26, 3.1, 'RCP_4872', 0),
(4873, '겨울 규동', '고춧가루 1큰술, 쌀 2컵, 된장 2큰술, 양파 1개, 다진마늘 1큰술', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n3. 야채를 데쳐서 찬물에 헹군다', 'EXTERNAL_API', 25, 21, 3.6, 'RCP_4873', 0),
(4874, '해장용 만두국', '연근 200g, 새우 200g, 양파 1개, 깨소금 1작은술, 다진마늘 1큰술, 가지 2개, 시금치 100g', '1. 그릇에 담아 깨소금을 뿌린다\n2. 재료를 깨끗이 씻어 준비한다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 두부를 넣고 5분 더 끓인다\n5. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 15, 27, 1.8, 'RCP_4874', 0),
